    "bn": "প্রয়োজনীয়তা এবং পরিমাণের পর্যালোচনা থেকে বাস্তবায়ন, পরিদর্শন এবং ডেলিভারি পর্যন্ত বিল্ডিং এলাকা পরিচালনা করুন।"
