    "bn": "অ্যাপ্লিকেশনটি গ্রহণ করুন এবং অধ্যয়ন করুন, তারপর প্রকল্পের ধরন এবং অবস্থান অনুযায়ী ক্ষমতা এবং প্যাকেজিং সময় নিশ্চিত করুন।"
