  "استمر في خدمة عملائك،": {
    "en": "Continue to serve your customers,",
    "bn": "আপনার গ্রাহকদের সেবা চালিয়ে যান,"
  },
  "استمرارية المنشأة تحتاج إلى توزيع واضح للمهن والورديات والمهام، وإلى تمييز الأعمال المجدولة عن البلاغات التصحيحية. تساعد الخدمة على تكوين فريق متعدد المهن ضمن نطاق تشغيلي يمكن متابعته وتعديله حسب طبيعة الموقع.": {
    "en": "The continuity of the organization requires a clear distribution of professions, roles and tasks, and to distinguish scheduled business from correctional reports. The service helps to form a multi-professional team within a range of operations that can be tracked and modified according to the nature of the site.",
    "bn": "সংস্থার ক্রমাগততা পেশা, ভূমিকা এবং কাজগুলির একটি পরিষ্কার বিতরণ প্রয়োজন, এবং সংশোধন প্রতিবেদন থেকে পরিকল্পিত ব্যবসা পার্থক্য করতে। পরিষেবাটি বিভিন্ন অপারেশনগুলির মধ্যে একটি মাল্টি পেশাদার দল গঠন করতে সহায়তা করে যা সাইটের প্রকৃতি অনুযায়ী ট্র্যাক এবং পরিবর্তন করা যেতে পারে।"
  },
  "استمرارية منشأتك تبدأ بفريق مناسب وتغطية واضحة للورديات والمهام. نساعدك على تكوين فريق متعدد المهن يلائم طبيعة الموقع والأعمال الوقائية والتصحيحية، مع مرونة تستجيب لتغير الاحتياج.": {
    "en": "The continuity of your facility starts with a suitable team and clear coverage for work shifts and tasks. We help you form a multi-professional team that fit the nature of the site, preventive and correction activities, with flexibility to respond to changing needs.",
    "bn": "আপনার সুবিধাগুলির ক্রমাগততা একটি উপযুক্ত দল এবং কাজের পরিবর্তন এবং কাজের জন্য পরিষ্কার কভারেজ দিয়ে শুরু হয়। আমরা আপনাকে একটি মাল্টি পেশাদারী দল গঠন করতে সাহায্য করি যা সাইটের প্রকৃতি, প্রতিরোধ এবং সংশোধন কার্যক্রমগুলি, পরিবর্তনশীল চাহিদাগুলির প্রতিক্রিয়া সহ।"
  },
