  "تبدأ الخدمة بفهم طبيعة الموقع والمهام الفعلية، لا بمجرد تسجيل عدد مطلوب. نحدد المهن والأعداد ومدة الاحتياج وساعات العمل ومتطلبات الموقع، ثم نبني نطاقًا يمكن تسعيره والتعاقد عليه ومتابعته بوضوح.": {
    "en": "The service begins with understanding the nature of the site and the actual tasks, not once you have registered the required number. We specify occupations, numbers, time of need, working hours and site requirements, and then build a range that can be priced, contracted and clearly followed.",
    "bn": "পরিষেবাটি সাইটের প্রকৃতি এবং প্রকৃত কাজগুলি বোঝার সাথে শুরু করে, একবার আপনি প্রয়োজনীয় সংখ্যা নিবন্ধন করেছেন না। আমরা কর্মসংস্থান, সংখ্যা, প্রয়োজনীয় সময়, কাজের সময় এবং সাইট প্রয়োজনীয়তা নির্দিষ্ট করি, এবং তারপর একটি পরিসীমা তৈরি করি যা মূল্যবান, চুক্তি এবং স্পষ্টভাবে অনুসরণ করা যেতে পারে।"
  },
  "تبقى الدفعات محفوظة في النظام في الحالتين.": {
    "en": "Payments remain stored in the system in both cases.",
    "bn": "পেমেন্ট দুই ক্ষেত্রে সিস্টেমে সংরক্ষণ করা হয়।"
  },
  "تُبنى المدة وفق احتياج المشروع وطبيعة النطاق، سواء كان مرحليًا أو موسميًا أو ممتدًا، ويُوضح ذلك في العرض قبل التعاقد.": {
    "en": "The duration is based on the project needs and the nature of the scope, whether it is phase, seasonal or extended, and is explained in the offer before contracting.",
    "bn": "সময়কাল প্রকল্পের চাহিদা এবং স্কেল প্রকৃতির উপর ভিত্তি করে, এটি ফেজ, মৌসুমী বা প্রসারিত হয়, এবং চুক্তি করার আগে অফারটি ব্যাখ্যা করা হয়।"
  },
  "تبوك": {
    "en": "by admin",
    "bn": "admin দ্বারা"
  },
  "تتأثر التكلفة بالمهنة والعدد والمدة والورديات وموقع العمل ومتطلبات الدخول أو التدريب ونطاق المسؤوليات، لذلك تُحدد بعد مراجعة تفاصيل الطلب.": {
    "en": "The cost is influenced by the profession, number, duration, work shifts, place of work, entry requirements, training and responsibility scope, so it is determined after reviewing the application details.",
    "bn": "খরচ পেশা, সংখ্যা, সময়কাল, কাজের পরিবর্তন, কাজের স্থান, প্রবেশের প্রয়োজনীয়তা, প্রশিক্ষণ এবং দায়বদ্ধতা প্রভাবিত হয়, তাই এটি আবেদন বিবরণ পর্যালোচনা পরে নির্ধারিত হয়।"
  },
