  "تتطلب معالجة فورية": {
    "bn": "অবিলম্বে পদক্ষেপ প্রয়োজন"
  },
  "تتغير احتياجات المشروع من التجهيز إلى التنفيذ والتشطيب. نوفر لشركات المقاولات والجهات المشغلة كوادر تناسب كل مرحلة، مع مرونة تساعدك على مواكبة البرنامج وتقليل أثر النقص المفاجئ. شركة دالي للتشغيل والصيانة مزود قوى عاملة وليست شركة مقاولات.": {
    "en": "The project needs are changing from processing to implementation and finishing. We provide contractors and operators as a suitable personnel for each stage, with flexibility to help you keep the program and minimize the impact of sudden deficiency. Dali Operations and Maintenance Company is a workforce provider and not a contractor.",
    "bn": "প্রকল্পের চাহিদা প্রক্রিয়াকরণ থেকে বাস্তবায়ন এবং সমাপ্তির জন্য পরিবর্তিত হয়। আমরা প্রতিটি পর্যায়ে উপযুক্ত কর্মীদের এবং অপারেটরদের সরবরাহ করি, যাতে আপনি প্রোগ্রামটি বজায় রাখতে সহায়তা করতে এবং হঠাৎ অভাবের প্রভাব কমাতে সহায়তা করতে নমনীয়তা সহ। ডালি অপারেশন এবং রক্ষণাবেক্ষণ কোম্পানি একটি শ্রমশক্তি প্রদানকারী এবং একটি নিয়োগকারী নয়।"
  },
  "تتغير احتياجات المشروع من التجهيز إلى التنفيذ والتشطيب. نوفر لشركات المقاولات والجهات المشغلة كوادر تناسب كل مرحلة، مع مرونة تساعدك على مواكبة البرنامج وتقليل أثر النقص المفاجئ. وإذا كان احتياجك عقد تنفيذ متكاملًا فيمكن تحويله مباشرة إلى قسم المقاولات وإدارة المشروعات.": {
    "en": "The project needs change from processing to implementation and finishing. We provide contractors and operators as a suitable personnel for each stage, with flexibility to help you keep the program and minimize the impact of sudden failure. If you need an integrated implementation contract, it can be converted directly to the contracting and project management department.",
    "bn": "প্রকল্পটি প্রক্রিয়া থেকে বাস্তবায়ন এবং শেষে পরিবর্তন প্রয়োজন। আমরা প্রতিটি পর্যায়ে উপযুক্ত কর্মীদের হিসাবে নিয়োগকারীদের এবং অপারেটরদের সরবরাহ করি, যা আপনাকে প্রোগ্রামটি বজায় রাখতে সহায়তা করে এবং হঠাৎ ব্যর্থতার প্রভাব কমাতে সহায়তা করে।"
  },
  "تتغير احتياجات منشآت الضيافة في مكة مع الإشغال والمواسم وطبيعة المرفق. تبدأ المراجعة بتحديد المواقع والورديات والمهام، ثم مطابقة المهن والأعداد والوثائق المطلوبة لكل موقع.": {
    "en": "The needs of hospitality facilities in Makkah change with occupation, seasons and nature of the facility. The review starts with the identification of locations, work shifts and tasks, and then match the professions, numbers and documents required for each site.",
    "bn": "মক্কায় হোস্টিং সুবিধাগুলির চাহিদাগুলি কর্মসংস্থান, ঋতু এবং সুবিধা প্রকৃতির সাথে পরিবর্তন করে। পর্যালোচনাটি স্থান, কাজের পরিবর্তন এবং কাজগুলির সনাক্তকরণের সাথে শুরু করে এবং তারপর প্রতিটি সাইটের জন্য প্রয়োজনীয় পেশা, সংখ্যা এবং নথিগুলি সমন্বয় করে।"
  },
