    "en": "Dali reads requests for facilities and projects within Mekka according to location, professions, numbers, duration and work shifts. The presence of a headquarters in the Rashfa district supports understanding of the nature of operational movement and seasonal demand in the city, and does not represent a promise of the time of arrival or availability of a number before the application review.",
