  "سنوي — 12 شهرًا، وأول دفعة بعد شهر من بداية العقد": {
    "en": "Annual — 12 months, the first time after a month of the start of the contract",
    "bn": "বার্ষিক - 12 মাস, চুক্তি শুরু এক মাস পর প্রথমবার"
  },
  "سنوية": {
    "bn": "বার্ষিক"
  },
  "سواء كنت تبحث عن قوى عاملة، أو فريق فني، أو تشغيل وصيانة، أو مقاولات في أي مدينة بالمملكة؛ فريق دالي جاهز لمراجعة طلبك.": {
    "en": "Whether you’re looking for workforce, technical team, operating and maintenance, or contractors in any city in the UK, Dali team is ready to review your application.",
    "bn": "আপনি কোনও শহরে শ্রমশক্তি, প্রযুক্তিগত দল, অপারেশন এবং রক্ষণাবেক্ষণ, বা যুক্তরাজ্যের যে কোনও শহরে নিয়োগকারীদের খুঁজছেন কিনা, ডালি দল আপনার আবেদন পর্যালোচনা করতে প্রস্তুত।"
  },
  "سواء كنت تحتاج إلى فني واحد أو فريق كامل، نرتب الخدمة بما يناسب طبيعة العمل وموقعه ومدته.": {
    "en": "Whether you need a single technician or a whole team, we arrange the service according to the nature, location and duration of the work.",
    "bn": "আপনি একটি একক প্রযুক্তিবিদ বা একটি সম্পূর্ণ দল প্রয়োজন কিনা, আমরা কাজের প্রকৃতি, অবস্থান এবং সময়কাল অনুযায়ী পরিষেবা ব্যবস্থা।"
  },
  "سواء كنت تحتاج إلى متخصص واحد أو فريق متكامل، نهيئ لك الحل الأنسب بحسب طبيعة العمل والمدة والموقع.": {
    "en": "Whether you need a single specialist or an integrated team, we prepare the best solution according to the nature of the work, duration and location.",
    "bn": "আপনি একটি একক বিশেষজ্ঞ বা একটি ইন্টিগ্রেটেড দল প্রয়োজন কিনা, আমরা কাজের প্রকৃতি, সময়কাল এবং অবস্থান অনুযায়ী সেরা সমাধান প্রস্তুত।"
  },
