  "شكراً لاهتمامك بالانضمام إلى دالي. تُستقبل طلبات التوظيف عبر قسم الوظائف في الموقع عند وجود فرص منشورة. اذكر تخصصك وخبرتك، ولا ترسل وثائق هوية داخل المحادثة.": {
    "en": "Thank you for your interest in joining Dali. Employment applications are accepted through the job department on the site when there are public opportunities. Remember your specialization and experience, and do not send identity documents within the conversation.",
    "bn": "ডালি যোগদান করার আগ্রহের জন্য ধন্যবাদ. পাবলিক সুযোগ থাকলে সাইটে কর্মসংস্থান বিভাগের মাধ্যমে কর্মসংস্থান আবেদন গ্রহণ করা হয়. আপনার বিশেষজ্ঞতা এবং অভিজ্ঞতা মনে রাখবেন, এবং কথোপকথনের মধ্যে পরিচয় নথি পাঠাবেন না।"
  },
  "شكرًا لتقييمك": {
    "en": "Thank you for your evaluation.",
    "bn": "আপনার মূল্যায়নের জন্য ধন্যবাদ।"
  },
  "شكراً لتواصلك مع شركة دالي للتشغيل والصيانة. رسالتك وصلت خارج ساعات الدوام الرسمي، وسيتم الرد عليك خلال ساعات العمل القادمة.": {
    "en": "Thank you for contacting Dali Operation and Maintenance Company. Your message arrived outside of the official hours and you will be answered within the next working hours.",
    "bn": "ডালি অপারেশন এবং রক্ষণাবেক্ষণ কোম্পানির সাথে যোগাযোগ করার জন্য ধন্যবাদ। আপনার বার্তাটি অফিসিয়াল সময় বাইরে পৌঁছেছে এবং আপনি পরবর্তী কাজের ঘন্টাগুলির মধ্যে উত্তর দেওয়া হবে।"
  },
  "شكراً لتواصلك يا {{name}}. استلمنا رسالتك برقم {{trackingCode}} خارج ساعات العمل، وسيعود فريق دالي لمتابعتك {{nextOpen}}. يمكنك الآن إضافة المهنة والعدد وموقع العمل والمدة لتسريع خدمتك.": {
    "en": "Thank you for contacting you, {{name}}. We have received your message on {{trackingCode}} outside of work hours and the Dali team will return to follow you {{nextOpen}}. You can now add the job, number, job location and duration to accelerate your service.",
    "bn": "আপনার সাথে যোগাযোগ করার জন্য ধন্যবাদ, {{name}}. আমরা কাজের সময় বাইরে {{trackingCode}} আপনার বার্তা পেয়েছি এবং ডালি দল আপনাকে অনুসরণ করতে ফিরে আসবে {{nextOpen}}. এখন আপনি আপনার পরিষেবাকে গতিশীল করতে চাকরি, নম্বর, কাজ অবস্থান এবং সময়কাল যোগ করতে পারেন।"
  },
