  "من القيود المرحلة لكل بنك": {
    "en": "Limitations for each bank.",
    "bn": "প্রতিটি ব্যাংকের জন্য সীমাবদ্ধতা।"
  },
  "من اليوم الأول.": {
    "en": "From the first day.",
    "bn": "প্রথম দিন থেকে।"
  },
  "من أول حديث،": {
    "en": "From the first word,",
    "bn": "প্রথম শব্দ থেকে,"
  },
  "من زوار الموقع": {
    "en": "Visitors of the site.",
    "bn": "সাইটের দর্শকরা"
  },
  "من شريك واحد.": {
    "en": "from one partner.",
    "bn": "একজন অংশীদার।"
  },
  "من شهر إلى 3 أشهر": {
    "bn": "এক থেকে তিন মাস"
  },
  "من فهم الاحتياج إلى انطلاق الفريق أو المشروع، نقدم مساراً واضحاً يقوده مختصون يراجعون طبيعة الموقع ومتطلبات القطاع والقدرة التشغيلية في المدينة.": {
    "en": "From understanding the need to start a team or project, we provide a clear track led by experts reviewing the nature of the site, sector requirements and operational capacity of the city.",
    "bn": "একটি দল বা প্রকল্প শুরু করার প্রয়োজন বুঝতে, আমরা সাইটের প্রকৃতি, সেক্টরের প্রয়োজনীয়তা এবং শহরের অপারেটিং ক্ষমতা পর্যালোচনা বিশেষজ্ঞদের নেতৃত্বে একটি পরিষ্কার ট্র্যাক সরবরাহ।"
  },
  "من مقرنا في حي الرصيفة بمكة المكرمة، نخدم المنشآت والمشروعات بفهم محلي لاحتياجات المدينة ومواسم الذروة والحج.": {
    "en": "From our headquarters in the Rashiva district of Makkah, we serve facilities and projects with a local understanding of the needs of the city, the peak season and the prayer.",
    "bn": "মক্কা রাশিভা জেলায় আমাদের সদর দপ্তর থেকে, আমরা শহরের চাহিদা, শীর্ষ ঋতু এবং হজ স্থানীয় বোঝার সাথে সুবিধা এবং প্রকল্পগুলি সেবা করি।"
  },
  "من مقرنا في حي الرصيفة نخدم احتياجات المنشآت والمشروعات في مكة بفهم محلي لطبيعة المدينة ومواسمها. نهيئ حلول قوى عاملة وتشغيل وصيانة تناسب الموقع والمهن والورديات والمدة المطلوبة.": {
    "en": "From our headquarters in the Rashfa neighborhood we serve the needs of facilities and projects in Makkah with a local understanding of the nature of the city and its qualifications. Developing workforce solutions, operating and maintenance suitable for the site, occupations, roads and duration required.",
    "bn": "রাশফা জেলায় আমাদের সদর দপ্তর থেকে আমরা মক্কায় সুবিধা এবং প্রকল্পের চাহিদাগুলিকে স্থানীয়ভাবে বুঝতে পারি শহরের প্রকৃতি এবং তার যোগ্যতা। কর্মক্ষমতা সমাধান, অপারেশন এবং রক্ষণাবেক্ষণ সাইট, কর্মসংস্থান, রাস্তা এবং প্রয়োজনীয় সময়সীমা জন্য উপযুক্ত।"
  },
  "من مقرنا في حي الرصيفة نراجع احتياجات المشروعات والمنشآت ومواقع الخدمة في مكة، مع مراعاة مواسم الذروة والحج.": {
    "en": "From our headquarters in the Rushia district we review the needs of projects, facilities and service sites in Makkah, taking into account the peak season and the hajar season.",
    "bn": "রাশিয়ার জেলায় আমাদের সদর দপ্তর থেকে আমরা মক্কায় প্রকল্প, সুবিধা এবং পরিষেবা সাইটের চাহিদাগুলি পর্যালোচনা করি, যার ফলে শীর্ষ মৌসুম এবং হাজার মৌসুমের বিবেচনা করা হয়।"
  },
  "من مكة إلى الرياض وجدة والدمام، نستقبل طلبات القوى العاملة والتشغيل والمقاولات ونرتب بدء العمل بما يناسب موقع المشروع.": {
    "en": "From Makkah to Riyadh, Jeddah and Dham, we receive workforce requests, operations, contractors and arrange the start of work according to the project’s location.",
    "bn": "মক্কা থেকে রিয়াদ, জেদা ও দাম পর্যন্ত আমরা শ্রমিকের অনুরোধ, অপারেশন, নিয়োগকর্তাদের গ্রহণ করি এবং প্রকল্পের অবস্থান অনুযায়ী কাজ শুরু করি।"
  },
  "من مكة إلى جميع مدن المملكة.": {
    "en": "From Makkah to all cities of the kingdom.",
    "bn": "রাজ্যের সব শহর থেকে।"
  },
