    "bn": "ব্যবসা এবং ব্যবস্থাপনা সুবিধাগুলির জন্য প্রযুক্তিগত এবং অপারেটিং দলগুলি তৈরি করুন যা কাজের ঘন্টা এবং সুবিধাটির প্রকৃতির উপযুক্ত, পরিষেবার ক্রমাগততা এবং কর্মীদের এবং দর্শকদের আরামের সমর্থন করে।"
