    "bn": "আমরা চাহিদা অনুযায়ী কাজের পরিবর্তন, অবস্থান এবং পরিষেবা পয়েন্ট অনুযায়ী বিতরণ করি যাতে আমরা অনুরোধের সময় সুবিধাটি প্রস্তুত রাখি।"
