    "bn": "একটি স্থায়ী পাসওয়ার্ড সেট করুন; সাময়িক স্থায়ীভাবে বাতিল করা হবে এবং আপনাকে আবার পরিবর্তন করতে অনুরোধ করা হবে না।"
