  "يتغير احتياج مشروع المقاولات من مرحلة إلى أخرى؛ فقد تحتاج البداية إلى مهن تختلف عن أعمال التشطيب أو التسليم. لذلك نربط طلب العمالة بالمرحلة والبرنامج المتوقع والموقع، حتى يكون العدد والمزيج المهني قابلين للمراجعة والتحديث.": {
    "en": "The needs of the contracting project change from stage to stage; you may need to start a career that is different from finishing or delivery. so we link employment request to the stage, the expected program and location, so the number and professional combination can be reviewable and updated.",
    "bn": "চুক্তি প্রকল্পের চাহিদা পর্যায়ে পরিবর্তন; আপনি একটি পেশা শুরু করতে হবে যা শেষ বা ডেলিভারি থেকে ভিন্ন। তাই আমরা পর্যায়ে, প্রত্যাশিত প্রোগ্রাম এবং অবস্থান লিঙ্ক, তাই সংখ্যা এবং পেশাদারী সংমিশ্রণ পর্যালোচনা এবং আপডেট করা যেতে পারে।"
  },
