    "bn": "আপনি আপনার সাধারণ ক্যারিয়ারের আগ্রহ নিবন্ধন করতে পারেন, এবং আপনি নিজেকে বিশেষজ্ঞ করার উপযুক্ত সুযোগ থাকলে আমরা আপনাকে ফিরে আসব।"
